-- SafetyTraining v20.050a
-- Reconcile live completion-v2 first-aid updates into reproducible repository state.
-- Idempotent, stable-key based, no generated UUIDs are persisted.

DO $do$
DECLARE
  r jsonb;
  v_lu uuid;
  v_luv uuid;
  v_course uuid;
  v_cv uuid;
  v_module uuid;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"key":"update:firstaid:scene-assessment","title":"Sicurezza della scena, allertamento e valutazione iniziale","summary":"Proteggere la scena, attivare i soccorsi e riconoscere rapidamente le condizioni che richiedono assistenza immediata.","tags":["safetytraining","first-aid","update","completion-v2"],"content":{"case":"Un collega è a terra vicino a una macchina ancora energizzata: prima si rende sicura la scena o si attiva chi può farlo, si impediscono altri accessi e si chiama il soccorso.","norm":"D.M. 15 luglio 2003 n. 388, art. 3 e allegati; D.Lgs. 81/2008 art. 45; procedure aziendali.","quiz":{"options":["Avvicinarsi immediatamente","Verificare che la scena sia sicura e non creare altre vittime","Spostare sempre la persona","Aspettare un collega"],"question":"Qual è la prima regola prima di prestare aiuto?","explanation":"La sicurezza del soccorritore e della scena viene prima dell’intervento: un secondo infortunato peggiora l’emergenza.","correct_index":1},"title":"Sicurezza della scena, allertamento e valutazione iniziale","detail":"L’addetto non sostituisce il personale sanitario. Prima impedisce che l’emergenza produca altre vittime, raccoglie informazioni essenziali e attiva il sistema di emergenza. La valutazione iniziale serve a riconoscere mancata risposta, respirazione assente o anormale, emorragia importante o altri segnali di allarme, senza perdere tempo in diagnosi. ","minutes":60,"quality":{"learner_ready":true,"teacher_ready":true,"scenario_based":true,"practical_focus":true},"summary":"Proteggere la scena, attivare i soccorsi e riconoscere rapidamente le condizioni che richiedono assistenza immediata.","visuals":["procedura-operativa-5-fasi.svg","stop-segnala-ripristina.svg"],"procedure":["osservare pericoli prima di avvicinarsi","usare DPI/barriere disponibili e non entrare in aree non sicure","verificare responsività e respirazione secondo l’addestramento ricevuto","attivare i soccorsi indicando luogo, evento, numero di persone e condizioni osservate","seguire le istruzioni dell’operatore di emergenza"],"common_errors":["correre verso l’infortunato ignorando il pericolo","fare diagnosi invece di descrivere segni","spostare una persona senza necessità o pericolo","ritardare la chiamata per completare una valutazione lunga"],"delivery_note":"La consultazione digitale supporta studio e preparazione ma non sostituisce l’esercitazione pratica prevista dal D.M. 388/2003.","guided_activity":["dimostrazione commentata","esecuzione individuale","scenario con variazione controllata","debriefing su tempi, decisioni e comunicazione"],"didactic_version":"completion-v2","final_assessment":false,"teacher_expansion":"Dimostrare, poi far esercitare individualmente con manichini/presidi didattici appropriati. Correggere tecnica e sequenza decisionale. Attenersi ai protocolli adottati dal corso, alle istruzioni del sistema di emergenza e alle competenze dell’addetto: il materiale non sostituisce indicazioni sanitarie."}},
    {"key":"update:firstaid:vital-functions","title":"Funzioni vitali e rianimazione: richiamo pratico guidato","summary":"Ripassare su manichino la sequenza prevista quando una persona non risponde e non respira normalmente.","tags":["safetytraining","first-aid","update","completion-v2"],"content":{"case":"Persona non responsiva in area sicura: organizzare chiamata, recupero DAE ove previsto, azioni pratiche su manichino e passaggio di informazioni.","norm":"D.M. 388/2003: aggiornamento della capacità di intervento pratico; protocolli vigenti adottati dal soggetto formatore e indicazioni del sistema di emergenza.","quiz":{"options":["Avvicinarsi immediatamente","Verificare che la scena sia sicura e non creare altre vittime","Spostare sempre la persona","Aspettare un collega"],"question":"Qual è la prima regola prima di prestare aiuto?","explanation":"La sicurezza del soccorritore e della scena viene prima dell’intervento: un secondo infortunato peggiora l’emergenza.","correct_index":1},"title":"Funzioni vitali e rianimazione: richiamo pratico guidato","detail":"Il docente dimostra e fa esercitare individualmente secondo i protocolli insegnati e le indicazioni del sistema di emergenza. L’obiettivo è ridurre esitazione ed errori: riconoscimento rapido, richiesta di aiuto, rianimazione di base e uso del DAE quando il partecipante è formato e l’organizzazione lo prevede. Non si improvvisano tecniche diverse da quelle apprese.","minutes":60,"quality":{"learner_ready":true,"teacher_ready":true,"scenario_based":true,"practical_focus":true},"summary":"Ripassare su manichino la sequenza prevista quando una persona non risponde e non respira normalmente.","visuals":["procedura-operativa-5-fasi.svg","stop-segnala-ripristina.svg"],"procedure":["verificare sicurezza e mancata risposta","attivare immediatamente il sistema di emergenza","eseguire sul manichino la sequenza pratica appresa con feedback del docente","usare il DAE seguendo istruzioni e addestramento quando disponibile e previsto","proseguire secondo protocollo fino al subentro dei soccorsi o cambiamento della condizione"],"common_errors":["perdere tempo cercando certezze diagnostiche","interrompere frequentemente senza motivo","usare tecniche non apprese","avvicinarsi durante analisi/scarica del DAE in modo non sicuro"],"delivery_note":"La consultazione digitale supporta studio e preparazione ma non sostituisce l’esercitazione pratica prevista dal D.M. 388/2003.","guided_activity":["dimostrazione commentata","esecuzione individuale","scenario con variazione controllata","debriefing su tempi, decisioni e comunicazione"],"didactic_version":"completion-v2","final_assessment":false,"teacher_expansion":"Dimostrare, poi far esercitare individualmente con manichini/presidi didattici appropriati. Correggere tecnica e sequenza decisionale. Attenersi ai protocolli adottati dal corso, alle istruzioni del sistema di emergenza e alle competenze dell’addetto: il materiale non sostituisce indicazioni sanitarie."}},
    {"key":"update:firstaid:trauma-bleeding","title":"Emorragie, ferite e traumi: protezione e gestione iniziale","summary":"Riconoscere situazioni traumatiche e applicare misure iniziali semplici senza aggravare il danno.","tags":["safetytraining","first-aid","update","completion-v2"],"content":{"case":"Caduta con ferita sanguinante e dolore cervicale: organizzare protezione, allerta, controllo iniziale del sanguinamento e minimizzazione dei movimenti.","norm":"D.M. 388/2003 allegati 3 e 4; procedure aziendali di primo soccorso.","quiz":{"options":["Avvicinarsi immediatamente","Verificare che la scena sia sicura e non creare altre vittime","Spostare sempre la persona","Aspettare un collega"],"question":"Qual è la prima regola prima di prestare aiuto?","explanation":"La sicurezza del soccorritore e della scena viene prima dell’intervento: un secondo infortunato peggiora l’emergenza.","correct_index":1},"title":"Emorragie, ferite e traumi: protezione e gestione iniziale","detail":"La priorità è controllare rischi immediati e chiedere aiuto. In presenza di sanguinamento importante si applicano le tecniche apprese e i presidi disponibili, proteggendosi dal contatto con sangue. Nei traumi si evitano movimenti inutili, soprattutto se il meccanismo fa sospettare coinvolgimento di cranio o colonna, salvo necessità di sicurezza o istruzioni dei soccorsi.","minutes":60,"quality":{"learner_ready":true,"teacher_ready":true,"scenario_based":true,"practical_focus":true},"summary":"Riconoscere situazioni traumatiche e applicare misure iniziali semplici senza aggravare il danno.","visuals":["procedura-operativa-5-fasi.svg","stop-segnala-ripristina.svg"],"procedure":["indossare protezioni prima del contatto con sangue","valutare gravità e attivare tempestivamente i soccorsi","applicare le tecniche di controllo dell’emorragia insegnate con i presidi previsti","evitare manipolazioni e riallineamenti improvvisati","monitorare e riferire cambiamenti ai soccorsi"],"common_errors":["toccare sangue senza protezione","rimuovere oggetti conficcati","far camminare una persona dopo trauma importante per “provare”","somministrare farmaci o cibi di propria iniziativa"],"delivery_note":"La consultazione digitale supporta studio e preparazione ma non sostituisce l’esercitazione pratica prevista dal D.M. 388/2003.","guided_activity":["dimostrazione commentata","esecuzione individuale","scenario con variazione controllata","debriefing su tempi, decisioni e comunicazione"],"didactic_version":"completion-v2","final_assessment":false,"teacher_expansion":"Dimostrare, poi far esercitare individualmente con manichini/presidi didattici appropriati. Correggere tecnica e sequenza decisionale. Attenersi ai protocolli adottati dal corso, alle istruzioni del sistema di emergenza e alle competenze dell’addetto: il materiale non sostituisce indicazioni sanitarie."}},
    {"key":"update:firstaid:medical-exposure","title":"Malori, ustioni, esposizioni e scenario integrato","summary":"Riconoscere segnali di allarme e attivare i soccorsi senza diagnosi o trattamenti improvvisati.","tags":["safetytraining","first-aid","update","completion-v2"],"content":{"case":"Malore dopo possibile esposizione: proteggere la scena, ricostruire l’evento, chiamare i soccorsi e preparare le informazioni utili.","norm":"D.M. 388/2003 allegati 3 e 4; schede di sicurezza/procedure; indicazioni del sistema di emergenza.","quiz":{"options":["Avvicinarsi immediatamente","Verificare che la scena sia sicura e non creare altre vittime","Spostare sempre la persona","Aspettare un collega"],"question":"Qual è la prima regola prima di prestare aiuto?","explanation":"La sicurezza del soccorritore e della scena viene prima dell’intervento: un secondo infortunato peggiora l’emergenza.","correct_index":1},"title":"Malori, ustioni, esposizioni e scenario integrato","detail":"Dolore toracico, difficoltà respiratoria, alterazione neurologica, convulsioni, reazioni importanti, ustioni e possibili intossicazioni richiedono riconoscimento dei segnali di allarme e rapido contatto con i soccorsi. Per sostanze chimiche si protegge prima il soccorritore e si consultano le informazioni disponibili, evitando neutralizzazioni o rimedi non previsti.","minutes":60,"quality":{"learner_ready":true,"teacher_ready":true,"scenario_based":true,"practical_focus":true},"summary":"Riconoscere segnali di allarme e attivare i soccorsi senza diagnosi o trattamenti improvvisati.","visuals":["procedura-operativa-5-fasi.svg","stop-segnala-ripristina.svg"],"procedure":["mettere in sicurezza scena e soccorritore","raccogliere sintomi/segni osservabili e tempi","chiamare il sistema di emergenza e seguirne le istruzioni","consultare scheda di sicurezza/procedura in caso di esposizione quando disponibile","non somministrare sostanze o farmaci di propria iniziativa"],"common_errors":["attendere che il malore passi quando ci sono segnali importanti","provocare vomito in caso di sospetta ingestione","toccare una persona ancora in contatto con una fonte elettrica","usare rimedi improvvisati su ustioni chimiche"],"delivery_note":"La consultazione digitale supporta studio e preparazione ma non sostituisce l’esercitazione pratica prevista dal D.M. 388/2003.","guided_activity":["dimostrazione commentata","esecuzione individuale","scenario con variazione controllata","debriefing su tempi, decisioni e comunicazione"],"didactic_version":"completion-v2","final_assessment":false,"teacher_expansion":"Dimostrare, poi far esercitare individualmente con manichini/presidi didattici appropriati. Correggere tecnica e sequenza decisionale. Attenersi ai protocolli adottati dal corso, alle istruzioni del sistema di emergenza e alle competenze dell’addetto: il materiale non sostituisce indicazioni sanitarie."}},
    {"key":"update:firstaid:a-complex-trauma","title":"Traumi complessi, più infortunati ed esposizioni industriali","summary":"Gestire priorità e comunicazione in scenari con più rischi o più persone coinvolte.","tags":["safetytraining","first-aid","group-a","update"],"content":{"case":"Due persone coinvolte e un pericolo residuo: organizzare area, chiamata, compiti degli addetti e passaggio di consegne.","norm":"D.M. 388/2003 allegato 3; piano di primo soccorso aziendale.","quiz":{"options":["Entrare subito per soccorrere","Controllare la scena e attivare risorse evitando nuovi esposti","Curare la persona che chiama più forte","Spostare tutti"],"question":"In un evento con più persone coinvolte e pericolo residuo, cosa viene prima?","explanation":"La gestione inizia da sicurezza e attivazione coordinata: non si aumenta il numero delle vittime.","correct_index":1},"title":"Traumi complessi, più infortunati ed esposizioni industriali","detail":"Nei contesti del Gruppo A sono plausibili eventi complessi. L’addetto non diventa soccorritore tecnico: rende sicura la scena per quanto di competenza, attiva risorse interne ed esterne, individua priorità evidenti e mantiene una comunicazione ordinata.","minutes":60,"quality":{"learner_ready":true,"teacher_ready":true,"practical_focus":true},"summary":"Gestire priorità e comunicazione in scenari con più rischi o più persone coinvolte.","procedure":["non entrare in una zona non resa sicura","attivare rapidamente ulteriori addetti e soccorsi","fornire numero di persone e pericoli osservati","prestare assistenza entro le competenze","preparare accesso e informazioni per i soccorritori professionali"],"delivery_note":"La consultazione digitale non sostituisce la pratica.","didactic_version":"completion-v2","final_assessment":false,"teacher_expansion":"Condurre una simulazione sicura e controllata, con ruoli, manichini/presidi didattici e debriefing. Evitare qualsiasi esposizione reale e mantenere il perimetro delle competenze di primo soccorso."}},
    {"key":"update:firstaid:a-simulation","title":"Simulazione completa, coordinamento e debriefing","summary":"Consolidare le capacità pratiche dall’allarme al passaggio di consegne.","tags":["safetytraining","first-aid","group-a","update"],"content":{"case":"Scenario scelto sui rischi reali dell’azienda: ogni partecipante assume almeno un ruolo operativo e riceve feedback specifico.","norm":"D.M. 388/2003 allegato 3; piano di primo soccorso aziendale.","quiz":{"options":["Entrare subito per soccorrere","Controllare la scena e attivare risorse evitando nuovi esposti","Curare la persona che chiama più forte","Spostare tutti"],"question":"In un evento con più persone coinvolte e pericolo residuo, cosa viene prima?","explanation":"La gestione inizia da sicurezza e attivazione coordinata: non si aumenta il numero delle vittime.","correct_index":1},"title":"Simulazione completa, coordinamento e debriefing","detail":"La simulazione verifica comportamento sotto pressione: sicurezza, richiesta di aiuto, valutazione, azione pratica appresa, comunicazione e coordinamento. Il debriefing ricostruisce decisioni e tempi e individua presidi non raggiungibili, informazioni mancanti e azioni di miglioramento.","minutes":60,"quality":{"learner_ready":true,"teacher_ready":true,"practical_focus":true},"summary":"Consolidare le capacità pratiche dall’allarme al passaggio di consegne.","procedure":["ricevere l’allarme e valutare rischi","assegnare compiti chiari","eseguire le capacità pratiche pertinenti su manichino/presidi","guidare i soccorsi e riferire informazioni","debriefing con azioni correttive organizzative"],"delivery_note":"La consultazione digitale non sostituisce la pratica.","didactic_version":"completion-v2","final_assessment":false,"teacher_expansion":"Condurre una simulazione sicura e controllata, con ruoli, manichini/presidi didattici e debriefing. Evitare qualsiasi esposizione reale e mantenere il perimetro delle competenze di primo soccorso."}}
  ]::jsonb) LOOP
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    VALUES(r->>'key',r->>'title',r->>'summary',60,'SafetyTraining completion-v2',ARRAY(SELECT jsonb_array_elements_text(r->'tags')),true,
      jsonb_build_object('learner_ready',true,'teacher_ready',true,'practical_focus',true,'didactic_version','completion-v2'))
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=60,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now()
    RETURNING id INTO v_lu;

    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at)
    VALUES(v_lu,1,'draft',r->'content',null)
    ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;
  END LOOP;

  -- Current live course metadata/snapshots.
  UPDATE public.courses SET metadata=metadata||jsonb_build_object(
      'didactic_version','completion-v2','material_complete',true,
      'learner_material_complete',true,'teacher_material_complete',true,
      'delivery_rules_are_metadata_only',true,'requires_admin_review',true,'learner_catalog_hidden',true),updated_at=now()
  WHERE stable_key IN ('agg_primo_soccorso_4h','agg_primo_soccorso_a_6h');

  SELECT id INTO v_course FROM public.courses WHERE stable_key='agg_primo_soccorso_4h';
  UPDATE public.courses SET family='primo_soccorso',nominal_minutes=240,description='Percorso di aggiornamento con componente pratica/presenza obbligatoria. SafetyTraining ne gestisce assegnazione e tracciamento, non simula la pratica online.',
    metadata=metadata||'{"blueprint_key":"first_aid_update","theory_minutes":0,"first_aid_group":"BC","practical_minutes":240,"requires_presence":true,"practical_separate":true,"source_course_code":"agg_primo_soccorso_4h","internal_non_certifying":true}'::jsonb WHERE id=v_course;
  SELECT id INTO v_cv FROM public.course_versions WHERE course_id=v_course AND version_number=1;
  UPDATE public.course_versions SET status='draft',published_at=null,
    syllabus_snapshot='{"group":"BC","source":"v20_026","digital_units":0,"theory_minutes":0,"nominal_minutes":240,"didactic_version":"completion-v2","material_minutes":240,"publication_gate":"Admin review + practical workflow configuration","material_complete":true,"practical_minutes":240,"learning_unit_count":4}'::jsonb,
    normative_snapshot='{"reference":"D.M. 388/2003","practical_training_required":true}'::jsonb WHERE id=v_cv;
  INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,'fa-refresh','Aggiornamento pratico delle capacità di primo soccorso',1,240)
    ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=1,nominal_minutes=240 RETURNING id INTO v_module;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"k":"update:firstaid:scene-assessment","p":1},{"k":"update:firstaid:vital-functions","p":2},{"k":"update:firstaid:trauma-bleeding","p":3},{"k":"update:firstaid:medical-exposure","p":4}]'::jsonb) LOOP
    SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>'k';
    INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    VALUES(v_module,v_luv,(r->>'p')::int,true,0,true,'{"material_complete":true,"practical_or_guided":true}'::jsonb)
    ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules;
  END LOOP;
  INSERT INTO public.course_practical_requirements(course_id,requirement_key,title,nominal_minutes,required,completion_mode,metadata)
  VALUES(v_course,'first_aid_practical','Aggiornamento pratico di primo soccorso',240,true,'in_person_training','{"group":"BC","source":"v20_026","normative_ref":"D.M. 388/2003","requires_external_record":true,"digital_completion_allowed":false}'::jsonb)
  ON CONFLICT(course_id,requirement_key) DO UPDATE SET title=excluded.title,nominal_minutes=excluded.nominal_minutes,required=true,completion_mode=excluded.completion_mode,metadata=excluded.metadata,updated_at=now();

  SELECT id INTO v_course FROM public.courses WHERE stable_key='agg_primo_soccorso_a_6h';
  UPDATE public.courses SET family='primo_soccorso',nominal_minutes=360,description='Percorso di aggiornamento con componente pratica/presenza obbligatoria. SafetyTraining ne gestisce assegnazione e tracciamento, non simula la pratica online.',
    metadata=metadata||'{"blueprint_key":"first_aid_update","theory_minutes":0,"first_aid_group":"A","practical_minutes":360,"requires_presence":true,"practical_separate":true,"source_course_code":"agg_primo_soccorso_a_6h","internal_non_certifying":true}'::jsonb WHERE id=v_course;
  SELECT id INTO v_cv FROM public.course_versions WHERE course_id=v_course AND version_number=1;
  UPDATE public.course_versions SET status='draft',published_at=null,
    syllabus_snapshot='{"group":"A","source":"v20_026","digital_units":0,"theory_minutes":0,"nominal_minutes":360,"didactic_version":"completion-v2","material_minutes":360,"publication_gate":"Admin review + practical workflow configuration","material_complete":true,"practical_minutes":360,"learning_unit_count":6}'::jsonb,
    normative_snapshot='{"reference":"D.M. 388/2003","practical_training_required":true}'::jsonb WHERE id=v_cv;
  INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,'fa-refresh','Aggiornamento pratico delle capacità di primo soccorso',1,240)
    ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=1,nominal_minutes=240;
  INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,'fa-a-extra','Approfondimento pratico Gruppo A',2,120)
    ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=2,nominal_minutes=120;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"m":"fa-refresh","k":"update:firstaid:scene-assessment","p":1},{"m":"fa-refresh","k":"update:firstaid:vital-functions","p":2},{"m":"fa-refresh","k":"update:firstaid:trauma-bleeding","p":3},{"m":"fa-refresh","k":"update:firstaid:medical-exposure","p":4},{"m":"fa-a-extra","k":"update:firstaid:a-complex-trauma","p":5},{"m":"fa-a-extra","k":"update:firstaid:a-simulation","p":6}]'::jsonb) LOOP
    SELECT id INTO v_module FROM public.course_modules WHERE course_version_id=v_cv AND module_key=r->>'m';
    SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>'k';
    INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    VALUES(v_module,v_luv,(r->>'p')::int,true,0,true,'{"material_complete":true,"practical_or_guided":true}'::jsonb)
    ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules;
  END LOOP;
  INSERT INTO public.course_practical_requirements(course_id,requirement_key,title,nominal_minutes,required,completion_mode,metadata)
  VALUES(v_course,'first_aid_practical','Aggiornamento pratico di primo soccorso',360,true,'in_person_training','{"group":"A","source":"v20_026","normative_ref":"D.M. 388/2003","requires_external_record":true,"digital_completion_allowed":false}'::jsonb)
  ON CONFLICT(course_id,requirement_key) DO UPDATE SET title=excluded.title,nominal_minutes=excluded.nominal_minutes,required=true,completion_mode=excluded.completion_mode,metadata=excluded.metadata,updated_at=now();

  -- Provenance already registered in v20.046 source library.
  FOR r IN SELECT value FROM jsonb_array_elements('["update:firstaid:scene-assessment","update:firstaid:vital-functions","update:firstaid:trauma-bleeding","update:firstaid:medical-exposure","update:firstaid:a-complex-trauma","update:firstaid:a-simulation"]'::jsonb) LOOP
    SELECT id INTO v_lu FROM public.learning_units WHERE stable_key=r#>>'{}';
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
    VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}'::jsonb)
    ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
  END LOOP;
END $do$;
